import * as fs from 'node:fs/promises';
import type { FileHandle } from 'node:fs/promises';
import path from 'node:path';

export interface WavRecorderOptions {
  sampleRate?: number;
  channels?: number;
  bitsPerSample?: number;
  maxBytes?: number; // max on-disk bytes per part, including the 44-byte header
}

interface WavFormat {
  sampleRate: number;
  channels: number;
  bitsPerSample: number;
}

const HEADER_SIZE = 44;

function wavHeader(opts: WavFormat): Buffer {
  const { sampleRate, channels, bitsPerSample } = opts;
  const blockAlign = (channels * bitsPerSample) / 8;
  const byteRate = sampleRate * blockAlign;
  const h = Buffer.alloc(HEADER_SIZE);
  h.write('RIFF', 0, 'ascii');
  h.writeUInt32LE(36, 4); // 36 + dataSize, patched on finalize
  h.write('WAVE', 8, 'ascii');
  h.write('fmt ', 12, 'ascii');
  h.writeUInt32LE(16, 16); // fmt chunk size
  h.writeUInt16LE(1, 20); // PCM
  h.writeUInt16LE(channels, 22);
  h.writeUInt32LE(sampleRate, 24);
  h.writeUInt32LE(byteRate, 28);
  h.writeUInt16LE(blockAlign, 32);
  h.writeUInt16LE(bitsPerSample, 34);
  h.write('data', 36, 'ascii');
  h.writeUInt32LE(0, 40); // dataSize, patched on finalize
  return h;
}

// Rotation naming (PLAN-013): part 1 keeps the ADR-007 <stem>.wav bundle
// name; when maxBytes is reached the part is finalized and recording
// continues in <stem>.part-NNN.wav siblings. Opened with 'wx' like part 1,
// so a name collision fails loudly rather than clobbering.
function partPathFor(filePath: string, part: number): string {
  if (part === 1) return filePath;
  const stem = filePath.replace(/\.wav$/i, '');
  return `${stem}.part-${String(part).padStart(3, '0')}.wav`;
}

// Opt-in session audio capture (PLAN-010): appends the same linear16 PCM
// that goes to the STT stream into a canonical WAV so the Review page can
// replay it. Writes are serialized like MarkdownSessionWriter's queue so
// chunks land in arrival order.
export class WavRecorder {
  private queue: Promise<unknown> = Promise.resolve();
  private fh: FileHandle | null = null;
  private payloadBytes = 0; // PCM bytes in the currently open part
  private totalBytes = 0; // PCM bytes summed across all parts
  private readonly parts: string[] = [];
  private readonly blockAlign: number;
  private readonly payloadCap: number;
  private done = false;
  private paused = false;

  private constructor(
    private readonly filePath: string,
    private readonly fmt: WavFormat,
    maxBytes: number | undefined,
  ) {
    this.blockAlign = (fmt.channels * fmt.bitsPerSample) / 8;
    this.payloadCap =
      maxBytes === undefined ? Infinity : maxBytes - HEADER_SIZE;
  }

  static async create(
    filePath: string,
    opts: WavRecorderOptions = {},
  ): Promise<WavRecorder> {
    const fmt: WavFormat = {
      sampleRate: opts.sampleRate ?? 16_000,
      channels: opts.channels ?? 1,
      bitsPerSample: opts.bitsPerSample ?? 16,
    };
    const rec = new WavRecorder(filePath, fmt, opts.maxBytes);
    // A cap that cannot hold one sample frame is a config bug: fail the
    // session start rather than record nothing.
    if (
      opts.maxBytes !== undefined &&
      opts.maxBytes < HEADER_SIZE + rec.blockAlign
    ) {
      throw new RangeError(
        `maxBytes ${opts.maxBytes} cannot hold the header plus one sample frame`,
      );
    }
    await fs.mkdir(path.dirname(filePath), { recursive: true });
    rec.fh = await fs.open(filePath, 'wx');
    await rec.fh.write(wavHeader(fmt));
    rec.parts.push(filePath);
    return rec;
  }

  append(chunk: Buffer): Promise<void> {
    if (this.paused) return Promise.resolve();
    return this.enqueue(async () => {
      if (!this.fh || this.done) return;
      let view = chunk;
      while (view.length > 0) {
        const room = this.payloadCap - this.payloadBytes;
        if (room < this.blockAlign) {
          await this.rotate();
          continue;
        }
        const fh = this.fh;
        if (!fh) return;
        // split at sample boundaries, never mid-sample and never over the cap
        const n = Math.min(
          view.length,
          Math.floor(room / this.blockAlign) * this.blockAlign,
        );
        await fh.write(view.subarray(0, n));
        this.payloadBytes += n;
        this.totalBytes += n;
        view = view.subarray(n);
      }
    });
  }

  get bytesWritten(): number {
    return this.totalBytes;
  }

  get partPaths(): readonly string[] {
    return this.parts;
  }

  get partCount(): number {
    return this.parts.length;
  }

  pause(): void {
    this.paused = true;
  }

  resume(): void {
    this.paused = false;
  }

  get isPaused(): boolean {
    return this.paused;
  }

  async finalize(): Promise<void> {
    await this.enqueue(async () => {
      if (!this.fh || this.done) return;
      this.done = true;
      await this.closePart();
    });
  }

  async abort(): Promise<void> {
    await this.enqueue(async () => {
      this.done = true;
      const fh = this.fh;
      this.fh = null;
      if (fh) await fh.close();
      for (const p of this.parts) {
        await fs.unlink(p).catch(() => {});
      }
    });
  }

  // Finalize the open part (sizes patched, handle closed) then open the
  // next numbered part. Runs inside the enqueued write op so a rotate can
  // never interleave with another append or with finalize/abort; at most
  // one part is ever open and every completed part is a standalone WAV.
  private async rotate(): Promise<void> {
    await this.closePart();
    const next = partPathFor(this.filePath, this.parts.length + 1);
    this.fh = await fs.open(next, 'wx');
    await this.fh.write(wavHeader(this.fmt));
    this.parts.push(next);
    this.payloadBytes = 0;
  }

  private async closePart(): Promise<void> {
    const fh = this.fh;
    if (!fh) return;
    const sizes = Buffer.alloc(4);
    sizes.writeUInt32LE(36 + this.payloadBytes, 0);
    await fh.write(sizes, 0, 4, 4);
    sizes.writeUInt32LE(this.payloadBytes, 0);
    await fh.write(sizes, 0, 4, 40);
    await fh.close();
    this.fh = null;
  }

  private enqueue<T>(op: () => Promise<T>): Promise<T> {
    const run = this.queue.then(op);
    this.queue = run.catch(() => {});
    return run;
  }
}


